from format_lecon import Lesson,paras,steps,table,ABBR,D
from html import escape
ABBR.update({'PIO':'pression intraoculaire','OCT':'tomographie par cohérence optique','BPCO':'bronchopneumopathie chronique obstructive','PEAG':'pustulose exanthématique aiguë généralisée','i.v.':'intraveineux','p.ex.':'par exemple'})
texts={k:(D/'evidence'/f'{k}_frais.txt').read_text().splitlines() for k in ('diamox','timoptic')}
def q(drug,start):
 found=[s for s in texts[drug] if s.startswith(start)]
 assert len(found)==1,(drug,start,len(found))
 return '<blockquote><p>« '+escape(found[0].removeprefix('·'))+' »</p></blockquote>'
def d(s):return q('diamox',s)
def t(s):return q('timoptic',s)
l=Lesson('Glaucome aigu par fermeture de l’angle',6)
diamox=l.subwindow('diamox','Acétazolamide : Diamox, formes et précautions suisses',paras('Diamox contient de l’acétazolamide. Les comprimés à 250 mg relèvent de Swissmedic 21191 ; la poudre injectable à 500 mg relève de 22002. La notice est commune, mais les formes ne sont pas interchangeables sans prescription de la voie et de la dose.',
'Les extraits suivants concernent l’adulte. Une dose initiale éventuelle de 500 mg ne doit pas être additionnée sans calcul à toutes les prises suivantes. L’équipe doit fixer une prescription explicite et calculer le cumul sur 24 heures dans la plage de la notice. Ce traitement ne dispense pas de lever le mécanisme de fermeture.')+
'<h3>Dose et administration</h3>'+d('Dans les cas aigus:')+d('Passer dès que possible')+d("Dissoudre le contenu de l'ampoule")+d('Pour une administration orale.')+d("Le pH de l'acétazolamide parentérale")+d('La préparation ne contient pas de conservateur.')+
'<h3>Contre-indications</h3>'+d('Hypersensibilité à la substance active')+d('Un traitement au long cours par Diamox est contre-indiqué')+d("L'utilisation de Diamox est contre-indiquée chez les patients")+
'<h3>Surveillance et alertes</h3>'+d("Le traitement avec l'acétazolamide peut causer")+d('Une prudence particulière est recommandée')+d("Lors d'un traitement au long cours avec Diamox")+d("Des cas de décès, bien que rares")+d("Des cas graves d'oedème pulmonaire")+d("L'oedème pulmonaire non cardiogénique est survenu")+d("Des cas d'épanchement/de décollement choroïdien")+
'<h3>Interactions à vérifier</h3>'+d("L'utilisation concomitante de l'acétazolamide et de l'acide acétylsalicylique")+d("L'acétazolamide est un diurétique avec effets kaliurétiques")+d('En raison des effets kaliurétiques')+d("L'utilisation concomitante avec d'autres inhibiteurs")+paras('Cette sélection met en évidence les interactions utiles au contexte aigu. La liste complète de la notice et les traitements réellement pris doivent être revus. Ne pas ajouter automatiquement un autre inhibiteur de l’anhydrase carbonique à un traitement systémique.')+
'<h3>Grossesse, allaitement et âge</h3>'+d('Il manque des études contrôlées')+d("L'acétazolamide est excrété dans le lait maternel.")+paras('La notice indique que l’administration aux enfants et adolescents n’a pas été étudiée. Aucun schéma pédiatrique n’est extrapolé ici. Chez une personne âgée, la fonction rénale et les troubles hydroélectrolytiques nécessitent une attention particulière.'),(53,))
timoptic=l.subwindow('timoptic','Timolol : Timoptic, collyre et risques systémiques',paras('Cette fenêtre concerne Timoptic collyre 0,25 % ou 0,5 %, Swissmedic 41634. Elle ne concerne pas Timoptic-XE ni une association fixe. Le schéma usuel cité ne constitue pas à lui seul un protocole de crise aiguë et ne permet pas d’attendre plusieurs semaines pour contrôler une crise.')+
'<h3>Posologie usuelle de la notice</h3>'+t('La dose initiale usuelle est de 1 goutte de Timoptic 0,25% dans')+t("L'utilisation de deux bêta-bloquants topiques")+t('La résorption systémique est réduite')+
'<h3>Fermeture de l’angle</h3>'+t("Lorsqu'on a recours à Timoptic pour réduire")+paras('Cette mention ne justifie pas un myotique dans toutes les fermetures secondaires. La pilocarpine peut aggraver certains mécanismes cristalliniens ou rétrolenticulaires. Le diagnostic du mécanisme précède le choix de l’association, avec un traitement spécialisé immédiat.')+
'<h3>Contre-indications</h3>'+t('·maladie respiratoire réactive')+t('·bradycardie sinusale')+t('·hypersensibilité au principe actif')+
'<h3>Précautions et interactions</h3>'+t("Comme d'autres médicaments ophtalmiques à usage local")+t('En raison de leurs effets négatifs')+t('Les bêta-bloquants doivent être utilisés avec prudence chez les patients susceptibles')+t('Lorsque Timoptic est utilisé en même temps')+paras('Un collyre peut donc provoquer une bradycardie, une hypotension ou un bronchospasme. Vérifier le pouls, les antécédents respiratoires et cardiaques, ainsi que les traitements associés. La réduction de l’absorption ne supprime pas les contre-indications.')+
'<h3>Grossesse et allaitement</h3>'+t('On ne dispose pas de données adéquates')+t('Le timolol a été retrouvé dans le lait maternel.')+
'<h3>Administration</h3>'+t('Les patients doivent être rendus attentifs')+paras('En situation de crise, la surveillance reste rapprochée et adaptée à l’évolution. Le délai de contrôle mentionné dans la notice pour apprécier la stabilisation d’un traitement chronique n’est pas applicable au tri urgent.'),(54,52))
l.add('Le {glaucome aigu par fermeture de l’angle} est une urgence ophtalmologique. L’obstruction de l’évacuation de l’humeur aqueuse provoque une forte hausse de pression. Une douleur oculaire avec baisse visuelle, rougeur ou nausées impose une évaluation immédiate.',paras('L’expression usuelle « glaucome aigu » décrit la crise symptomatique. Une fermeture aiguë peut être reconnue avant que des lésions glaucomateuses du nerf optique soient démontrées. Cette distinction de vocabulaire ne réduit pas l’urgence.',
'Ne pas assimiler toute fermeture de l’angle à une crise aiguë : des formes chroniques ou intermittentes existent. Inversement, un tableau brutal ne relève pas du calendrier d’un glaucome chronique stable.'),(14,50,51,52))
l.add('Le {terrain anatomique et médicamenteux} aide à orienter l’enquête. Un angle étroit, l’hypermétropie et certaines modifications du cristallin favorisent la fermeture. L’absence de facteur connu n’exclut pas une crise.',paras('L’anatomie de la chambre antérieure compte davantage qu’une étiquette isolée de terrain. L’âge, les antécédents et l’examen de l’autre œil complètent l’évaluation. La maladie n’est pas réservée à un sexe ou à une origine.',
'Rechercher une dilatation récente, un médicament nouvellement introduit et des épisodes brefs de flou ou de halos. Les sources retenues ne permettent pas de chiffrer une fréquence suisse comparable pour les dix diagnostics du lot. Aucun rang numérique n’est affirmé.'),(14,50,51))
l.add('Le {mécanisme de fermeture} détermine le traitement causal. Un blocage pupillaire et une poussée venant de l’arrière ne se traitent pas de la même façon. Faire baisser la pression ne démontre pas que l’obstacle a disparu.',table(['Élément','Explication','Conséquence'],[
['Humeur aqueuse','Liquide produit dans l’œil et évacué notamment par le trabéculum.','Une obstruction de l’accès au drainage peut faire monter la pression.'],
['Blocage pupillaire','Le passage du liquide entre les compartiments est gêné et l’iris peut se bomber.','Une iridotomie crée une autre voie de circulation lorsqu’elle est indiquée.'],
['Iris plateau ou encombrement antérieur','La configuration périphérique peut maintenir un angle étroit.','Un trou perméable dans l’iris ne prouve pas une ouverture suffisante de tout l’angle.'],
['Cause cristallinienne ou rétrolenticulaire','Le déplacement des structures vers l’avant peut fermer l’angle.','Éviter de traiter automatiquement toute fermeture par un myotique.']
])+paras('Une fermeture secondaire peut être liée à une autre affection oculaire ou à un médicament. Le traitement doit agir sur cette cause. L’évaluation anatomique ne se résume pas au diamètre de la pupille.'),(14,49,52))
l.add('Les {signes de crise} justifient un accès immédiat à l’ophtalmologie. Une baisse visuelle douloureuse avec œil rouge ne doit pas attendre un rendez-vous de dépistage. Des vomissements ou une céphalée peuvent masquer la plainte oculaire.',paras('Demander explicitement s’il existe un flou, des halos, une rougeur ou une douleur de l’œil devant une céphalée accompagnée de nausées. Le tableau n’est pas automatiquement digestif ou migraineux. Examiner sans retarder le transfert spécialisé.',
'Ne pas attendre un champ visuel, une imagerie du nerf optique ou une amélioration spontanée pour adresser une crise suspectée. Si les moyens d’examen manquent, organiser l’évaluation urgente plutôt que rassurer sur une mesure absente. Le patient ne doit pas conduire avec cette baisse visuelle : prévoir un transport adapté.',
'Une faiblesse, un trouble de la parole ou une autre anomalie neurologique impose aussi le parcours d’urgence correspondant. Une hypothèse oculaire ne doit pas occulter une urgence associée.'),(4,50,51))
l.add('L’{anamnèse ciblée} précise le début, les yeux atteints et les expositions. Elle recherche aussi les contre-indications aux traitements hypotenseurs. Les données utiles doivent accompagner le patient lors de l’orientation.',steps('Noter l’heure de début, la douleur, le flou, les halos, les nausées et l’évolution.','Rechercher des épisodes antérieurs, une chirurgie, une inflammation et une dilatation récente.','Recenser tous les médicaments, y compris collyres et produits pris sans ordonnance.','Demander notamment une prise de topiramate devant une présentation atypique ou bilatérale.','Vérifier allergies aux sulfamides, maladie rénale ou hépatique, troubles électrolytiques et grossesse éventuelle.','Avant un bêtabloquant local, rechercher asthme, bradycardie, trouble de conduction et insuffisance cardiaque.'),(50,51,52,53,54))
l.add('L’{examen urgent} porte sur la vision, la cornée, la pupille, la chambre antérieure et la pression. L’examen de l’angle précise la fermeture. Les deux yeux doivent être évalués, même si un seul est douloureux.',paras('Mesurer l’acuité œil par œil lorsque c’est possible. Observer rougeur, transparence cornéenne et réaction pupillaire à la lampe à fente. Une cornée œdémateuse peut gêner l’examen et le traitement laser.',
'Mesurer la pression intraoculaire (PIO) et examiner l’angle par gonioscopie. Une chambre peu profonde et une pupille anormale renforcent l’orientation sans remplacer l’ensemble du bilan. Un chiffre isolé ne suffit pas à classer le mécanisme.',
'L’évaluation du nerf optique et du champ visuel est utile pour le retentissement, mais ne doit pas retarder le traitement de la crise. Documenter les constatations initiales pour juger ensuite de l’évolution.'),(14,50,52))
l.add('L’{approche syndromique} sépare crise primitive et fermeture secondaire. Un autre œil rouge douloureux peut ressembler à ce tableau. L’orientation thérapeutique doit rester révisable lorsque les constatations ne concordent pas.',table(['Situation','Risque de confusion','Conduite'],[
['Douleur, œil rouge et baisse visuelle','Assimilation à une conjonctivite banale.','Examen urgent et mesure de la pression.'],
['Céphalée avec vomissements','Attribution uniquement digestive ou neurologique.','Rechercher une plainte et des signes oculaires sans ignorer les autres urgences.'],
['Fermeture avec cause cristallinienne ou rétrolenticulaire','Application automatique du schéma du bloc pupillaire.','Déterminer le mécanisme avant le choix d’un myotique.'],
['Aggravation visuelle après nouveau médicament','Interprétation comme simple échec de traitement.','Rechercher un effet indésirable et réévaluer les structures oculaires.'],
['Amélioration de la douleur après traitement','Conclusion prématurée de guérison.','Recontrôler pression et anatomie, organiser le traitement causal.']
]),(50,51,52,53))
l.add('Le diagnostic positif associe {fermeture de l’angle et hyperpression aiguë}. Il précise si une cause secondaire est présente. Le bilan ultérieur distingue le dommage du nerf optique d’une simple élévation de pression.',paras('La gonioscopie examine la zone où l’iris peut obstruer le drainage. Elle se combine à la tonométrie et à l’examen clinique. Les symptômes seuls ne déterminent ni le mécanisme ni le degré de lésion.',
'Une mesure rassurante entre deux épisodes n’efface pas une histoire évocatrice de fermeture intermittente. Inversement, une pression élevée n’est pas toujours liée à un angle fermé. L’analyse doit relier le chiffre à l’anatomie et au contexte.'),(14,50,52))
l.add('Les {examens complémentaires} servent à préciser le mécanisme et le retentissement. La gonioscopie reste centrale pour l’angle. Un examen différé de surveillance ne doit jamais retarder la prise en charge aiguë.',
'<h3>9.a — Référence diagnostique</h3>'+paras('La gonioscopie, associée à la mesure de pression et à la lampe à fente, caractérise la fermeture. L’examen doit rechercher les causes secondaires qui modifieraient la stratégie.')+
'<h3>9.b — Première intention</h3>'+paras('Documenter acuité, pression, cornée, pupille et profondeur de chambre. Examiner l’œil opposé et vérifier les traitements déjà administrés. Les examens biologiques utiles au traitement systémique se coordonnent avec la prise en charge urgente.')+
'<h3>9.c — Examens dirigés</h3>'+paras('Une imagerie du segment antérieur peut aider lorsque l’anatomie reste incertaine ou l’examen difficile. Elle complète l’examen spécialisé. La tomographie par cohérence optique (OCT) n’est pas un substitut universel à la gonioscopie.')+
'<h3>9.d — Seconde intention</h3>'+paras('Après contrôle de la crise, évaluer le nerf optique et le champ visuel, puis établir les références de suivi. Une anomalie résiduelle demande une interprétation avec les constatations initiales et les pathologies associées.'),(14,50,52))
l.add('L’{arbre décisionnel} associe urgence, confirmation et recherche du mécanisme. Le traitement de la pression prépare le traitement causal. L’échec ou l’aggravation impose une réévaluation immédiate.',steps('Si baisse visuelle douloureuse avec rougeur ou signes associés, alors organiser l’évaluation ophtalmologique immédiate.','Si fermeture avec hyperpression confirmée, alors rechercher la cause et vérifier les contre-indications médicamenteuses.','Si mécanisme primitif approprié, alors associer traitement hypotenseur et levée de l’obstacle selon le spécialiste.','Si cause cristallinienne, rétrolenticulaire ou médicamenteuse, alors adapter le traitement à cette cause.','Si la cornée empêche le laser ou si la réponse est insuffisante, alors demander sans délai une stratégie spécialisée complémentaire.','Après amélioration, alors vérifier l’autre œil et organiser la prévention de récidive et le suivi.'),(14,49,50,51,52))
l.add('La {prise en charge suisse} doit être immédiate et surveillée. Elle associe baisse de pression, soulagement et traitement du mécanisme. Les médicaments seuls ne remplacent pas le geste causal lorsqu’il est nécessaire.',
'<h3>11.A — But</h3>'+paras('Préserver la fonction visuelle, contrôler la crise et éviter sa récidive. L’orientation urgente et le traitement ne doivent pas attendre que toutes les explorations de suivi soient réalisées.')+
'<h3>11.B — Moyens</h3>'+paras('L’acétazolamide systémique peut réduire la production d’humeur aqueuse. Les formes, doses adultes et précautions suisses sont détaillées ici : ')+diamox+paras('Un bêtabloquant local peut participer au traitement si le terrain le permet : ')+timoptic+
paras('La pilocarpine a une place dans certains mécanismes primitifs, mais elle n’est pas un traitement automatique de toute fermeture. Son efficacité peut être limitée quand l’hyperpression est très importante. Les mécanismes cristalliniens ou rétrolenticulaires peuvent au contraire être aggravés par un myotique.',
'Aucun schéma dosé suisse de pilocarpine, de mannitol ou d’un autre collyre n’est affirmé sans notice de la présentation retenue. Leur choix et leur prescription relèvent du protocole spécialisé. Les deux fenêtres médicamenteuses ne constituent donc pas une ordonnance complète de crise.',
'L’iridotomie périphérique crée une voie de passage à travers l’iris lorsqu’elle est indiquée. L’iridoplastie agit sur la périphérie de l’iris. Une extraction cristallinienne peut faire partie de la stratégie selon l’anatomie et l’état du cristallin. Ces gestes n’ont pas tous la même indication ni le même calendrier.',
'La prise en charge de la douleur et des vomissements accompagne le traitement oculaire. Le choix des médicaments tient compte du mécanisme et des interactions. Un traitement symptomatique isolé ne suffit pas.')+
'<h3>11.C — Surveillance</h3>'+paras('Contrôler de façon rapprochée pression, vision, douleur et examen oculaire jusqu’à maîtrise de la crise. Surveiller aussi l’état général et les effets des médicaments. Après acétazolamide, une dyspnée nouvelle ou une aggravation oculaire doit faire rechercher une complication.',
'Vérifier fonction rénale, électrolytes et équilibre acido-basique selon le terrain et le traitement. Sous timolol, surveiller notamment pouls et respiration. Ne pas confondre les échéances de contrôle d’un traitement chronique avec celles d’une urgence.')+
'<h3>11.D — Pronostic et suivi</h3>'+paras('La récupération dépend des lésions déjà constituées et de la réponse au traitement. Le soulagement de la douleur ne garantit pas l’absence de dommage. Une pression normalisée ne justifie pas l’abandon du suivi.',
'L’œil opposé doit être examiné pour prévenir une crise lorsqu’il présente le même risque. La stratégie préventive après une crise primitive n’est pas identique à celle de tout angle étroit découvert sans symptôme. Le compte rendu doit préciser le geste réalisé, la suite et les signes de réévaluation urgente.'),(49,50,51,52,53,54))
l.add('La {prévention des récidives} repose sur le traitement de la cause et une information précise. L’autre œil et les médicaments déclenchants éventuels doivent être pris en compte. Une iridotomie n’annule pas tous les mécanismes de fermeture.',paras('Expliquer les symptômes qui imposent de reconsulter immédiatement. Fournir un moyen de joindre les urgences et vérifier la compréhension, en particulier après un épisode accompagné de douleur ou de vomissements.',
'Transmettre aux autres soignants la nature du problème et les traitements effectués. L’avertissement « glaucome » sans précision peut conduire à des décisions inadaptées. Le patient ne doit pas modifier seul ses traitements habituels ni utiliser un ancien collyre pour prévenir une crise.',
'Une dilatation peut être nécessaire pour une autre maladie oculaire. Le spécialiste en évalue les conditions de sécurité en fonction de l’angle et du traitement préalable. Une interdiction générale de tout examen dilaté serait inappropriée.'),(50,51,52))
l.add('Les {points clés} sont l’urgence, le mécanisme et la surveillance. Une crise douloureuse diffère du glaucome chronique silencieux. Une baisse de pression ne prouve pas que l’angle est durablement rouvert.',steps('Rechercher l’œil rouge douloureux devant céphalée, nausées et baisse visuelle.','Confirmer l’hyperpression et examiner l’angle.','Identifier une cause secondaire avant de choisir un myotique.','Vérifier les contre-indications rénales, électrolytiques, respiratoires et cardiaques.','Associer au traitement hypotenseur la stratégie causale indiquée.','Réévaluer une réponse insuffisante ou une aggravation après traitement.','Prévenir la récidive et examiner l’autre œil.'),(14,49,50,51,52,53,54))
l.quiz([
('Question 1 — Un œil rouge douloureux avec baisse visuelle peut-il attendre un contrôle de routine ?', 'Non. Une crise de fermeture de l’angle fait partie des urgences à rechercher immédiatement.'),
('Question 2 — Des vomissements excluent-ils une origine oculaire ?', 'Non. Ils peuvent accompagner la crise et masquer la plainte oculaire.'),
('Question 3 — Toute pression élevée démontre-t-elle une fermeture de l’angle ?', 'Non. Le mécanisme demande un examen anatomique, notamment une gonioscopie.'),
('Question 4 — Faut-il attendre le champ visuel avant de traiter une crise ?', 'Non. Les examens de retentissement ne doivent pas retarder la prise en charge aiguë.'),
('Question 5 — La pilocarpine convient-elle à toutes les fermetures ?', 'Non. Certains mécanismes cristalliniens ou rétrolenticulaires peuvent être aggravés par un myotique.'),
('Question 6 — Quel traitement rechercher devant une présentation atypique ou bilatérale ?', 'Notamment le topiramate, sans limiter l’enquête à ce seul médicament.'),
('Question 7 — Un flacon injectable de Diamox correspond-il à un comprimé ?', 'Non. La poudre injectable contient 500 mg ; le comprimé contient 250 mg. La voie et le cumul prescrit doivent être explicites.'),
('Question 8 — Une dose initiale de Diamox dispense-t-elle de calculer le total des prises ?', 'Non. La prescription doit intégrer cette dose dans le cumul sur 24 heures et tenir compte des contre-indications.'),
('Question 9 — Une insuffisance rénale ou un trouble électrolytique peut-il être ignoré ?', 'Non. Ils peuvent rendre l’acétazolamide dangereux ou contre-indiqué selon la situation décrite dans la notice.'),
('Question 10 — Le timolol en collyre est-il sans effet sur le cœur ou les bronches ?', 'Non. Une absorption systémique existe, avec des contre-indications cardiaques et respiratoires.'),
('Question 11 — Le schéma usuel de Timoptic constitue-t-il seul une ordonnance complète de crise ?', 'Non. Il ne traite pas à lui seul le mécanisme et ne remplace pas la surveillance urgente.'),
('Question 12 — Une douleur diminuée signifie-t-elle que le risque est levé ?', 'Non. Il faut contrôler la pression et l’anatomie et prévoir le traitement causal.'),
('Question 13 — L’autre œil peut-il être oublié parce qu’il ne fait pas mal ?', 'Non. Il doit être évalué pour organiser la prévention adaptée.'),
('Question 14 — Une iridotomie permet-elle de supprimer tout suivi ?', 'Non. Une fermeture résiduelle, un autre mécanisme ou des lésions constituées peuvent nécessiter des soins supplémentaires.')
],(14,49,50,51,52,53,54))
l.write()
